import{_ as t,a,b as o,c as n}from"./chunks/compare-toolbar.C9dGGdO9.js";import{_ as r,o as s,c as i,a2 as l}from"./chunks/framework.Dx-TCpNt.js";const b=JSON.parse('{"title":"Compare Reader","description":"The compare reader puts the same panel from two or more languages next to each other — or on top of each other — and lets you align the artwork so the…","frontmatter":{"description":"The compare reader puts the same panel from two or more languages next to each other — or on top of each other — and lets you align the artwork so the…"},"headers":[],"relativePath":"guide/compare.md","filePath":"guide/compare.md","lastUpdated":1794842245000}'),h={name:"guide/compare.md"};function d(g,e,c,p,m,u){return s(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="compare-reader" tabindex="-1">Compare Reader <a class="header-anchor" href="#compare-reader" aria-label="Permalink to &quot;Compare Reader&quot;">​</a></h1><p>The compare reader puts the same panel from two or more languages next to each other — or on top of each other — and lets you align the artwork so the comparison is actually honest.</p><figure class="shot"><img src="'+t+'" alt="Compare reader showing the same page in Japanese, Chinese and English side by side"><figcaption>Side-by-side mode with three languages. Each language is its own pane; alignment is stored per page and applied to exports.</figcaption></figure><h2 id="the-problem-it-solves" tabindex="-1">The problem it solves <a class="header-anchor" href="#the-problem-it-solves" aria-label="Permalink to &quot;The problem it solves&quot;">​</a></h2><p>Two editions of the same book rarely line up exactly: the raw and the scanlation are shifted, cropped or scaled differently. Comparing a page as a whole hides small differences. Comparing <strong>one panel at a time</strong>, with each language independently aligned, makes wording, tone and omissions visible.</p><h2 id="layouts" tabindex="-1">Layouts <a class="header-anchor" href="#layouts" aria-label="Permalink to &quot;Layouts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>Behaviour</th></tr></thead><tbody><tr><td><strong>Language chips</strong> (<code>JA</code>, <code>ZH</code>, <code>EN</code>, …)</td><td>Toggle a language on or off. A language missing on this page is disabled with a tooltip.</td></tr><tr><td>Drag a chip</td><td>Reorders the panes. The order is remembered.</td></tr><tr><td><code>↺</code></td><td>Restores the library&#39;s language order.</td></tr><tr><td><strong>Side by side</strong></td><td>One column per selected language. On a narrow window the panes stack vertically.</td></tr><tr><td><strong>Overlay</strong></td><td>All selected languages are drawn in the same box.</td></tr><tr><td><strong>Multiply</strong> (Overlay only)</td><td>Multiplies the layers so line art shows through.</td></tr><tr><td><strong>Aligning</strong> chips (Overlay only)</td><td>Chooses which language you are dragging, so two panes never move at once.</td></tr></tbody></table><h2 id="masking" tabindex="-1">Masking <a class="header-anchor" href="#masking" aria-label="Permalink to &quot;Masking&quot;">​</a></h2><p>Masking hides a language&#39;s artwork while you test your own comprehension — the manga-learner equivalent of covering the answer.</p><table tabindex="0"><thead><tr><th>Control</th><th>Behaviour</th></tr></thead><tbody><tr><td><strong>Mask: On / Off</strong></td><td>Master switch. <code>H</code> toggles it; <code>Shift+H</code> reveals everything.</td></tr><tr><td>Per-language <code>◐</code> / <code>◯</code> chips</td><td>Choose which languages are masked.</td></tr><tr><td><strong>Mask style</strong></td><td><strong>Blur</strong> or <strong>Solid</strong>.</td></tr><tr><td><strong>Mask all</strong></td><td>Re-masks every currently visible pane.</td></tr><tr><td><strong>Reveal all</strong></td><td>Turns the master switch off.</td></tr><tr><td><strong>Defaults…</strong></td><td>Remembers which languages start masked, across sessions.</td></tr><tr><td>Click a masked pane</td><td>Reveals it temporarily; click the artwork again to mask it.</td></tr></tbody></table><p>Masks are a <strong>reading preference only</strong>. HTML and PNG exports never include masks. Mask defaults are stored in the browser, not in the page JSON.</p><figure class="shot"><img src="'+a+'" alt="Compare reader with Chinese and English masked by a blur, the mask style selector and the default-mask checkboxes"><figcaption>Masking with Chinese and English hidden. Default masks remembers which languages start masked; clicking a masked pane reveals it temporarily.</figcaption></figure><h2 id="zoom-pan-and-scope" tabindex="-1">Zoom, pan and scope <a class="header-anchor" href="#zoom-pan-and-scope" aria-label="Permalink to &quot;Zoom, pan and scope&quot;">​</a></h2><ul><li><strong>Wheel</strong> over a pane zooms that language. The wheel is captured only while the pointer is inside a pane, so normal page scrolling still works elsewhere.</li><li><strong>Drag</strong> a pane to pan it.</li><li><strong>Drag/zoom</strong> scope has two modes: <strong>Whole page</strong> and <strong>This panel</strong>.</li><li>Hold <code>Alt</code> while dragging or scrolling to adjust only the current panel, whatever the default scope is.</li><li><strong>Previous panel / Next panel</strong> move the focused panel in reading order. Past the first or last panel of the page, they turn to the neighbouring page and focus its last or first panel instead. Pages excluded by preprocessing are skipped, chapter boundaries are crossed, and at the very start or end of the volume nothing moves. Unsaved edits still go through the usual save-mode check first.</li><li><strong>Reset all</strong> clears offsets in the current scope.</li></ul><p>Each language has <code>{ x, y, scale }</code>. <code>x</code> and <code>y</code> are fractions of the panel width and height; <code>scale</code> zooms the crop between 0.5× and 3×.</p><h3 id="auto-centring" tabindex="-1">Auto-centring <a class="header-anchor" href="#auto-centring" aria-label="Permalink to &quot;Auto-centring&quot;">​</a></h3><p>When the selected panel changes — previous / next, a keyboard shortcut, a jump from the sidebar or the notes overview, or a cross-page move — the compare reader scrolls the target panel into view.</p><ul><li>If the panel fits, it is centred; if it is taller than the viewport, its top edge is brought in with a small margin so the first line of art is not clipped.</li><li>A panel that is already comfortably visible is left alone; the reader does not yank the page on every selection change, and it stops fighting you once you scroll by hand.</li><li>On a cross-page jump, the scroll waits for the new page to render before aligning.</li><li>The scroll respects the system <strong>Reduce motion</strong> setting and becomes an instant jump when that is on.</li></ul><h2 id="alignment-modes" tabindex="-1">Alignment modes <a class="header-anchor" href="#alignment-modes" aria-label="Permalink to &quot;Alignment modes&quot;">​</a></h2><p>Alignment is stored in the page JSON, never baked into the images.</p><table tabindex="0"><thead><tr><th>Mode</th><th>Behaviour</th><th>Good for</th></tr></thead><tbody><tr><td><strong>Whole-page offset</strong></td><td>Dragging any panel translates the whole page for that language.</td><td>A whole scan is shifted by the same amount.</td></tr><tr><td><strong>Per-panel offset</strong></td><td>Each panel has its own offset.</td><td>Digital and print editions have different panel positions.</td></tr><tr><td><strong>Anchor alignment</strong></td><td>Click a feature point on the reference language, then the same point on another language; the offset is computed.</td><td>Precise, repeatable alignment of one detail.</td></tr><tr><td><strong>Grid snap</strong></td><td>Dragging snaps to a step of 0.5%, 1%, 2% or 5%.</td><td>Tidy, reproducible numeric offsets.</td></tr></tbody></table><p>Anchor mode shows a prompt with the reference language. Click a feature point in any cell first, then the same spot in another cell. <strong>Cancel anchor</strong> clears the pending point. The pending anchor is not saved.</p><h3 id="alignment-settings" tabindex="-1">Alignment settings <a class="header-anchor" href="#alignment-settings" aria-label="Permalink to &quot;Alignment settings&quot;">​</a></h3><p><strong>Alignment settings</strong> opens a panel with:</p><ul><li>The <strong>target</strong> language chips.</li><li>Exact <strong>X</strong>, <strong>Y</strong> and <strong>Scale</strong> inputs for the selected target.</li><li><strong>Reset all panels on this page</strong> — clears per-panel offsets; whole-page offsets are unaffected.</li><li><strong>Reset current panel</strong> — clears per-panel offsets for the selected panel only.</li><li><strong>Save as page preset</strong> / <strong>Save as chapter preset</strong> — stores the current alignment under <code>data/presets/align.json</code>.</li><li>Choose a preset, then <strong>Apply to this page</strong> or <strong>Apply to chapter</strong>; <strong>Delete</strong> removes it.</li></ul><p>Presets record the alignment mode, offsets, panel offsets and grid step. Applying a chapter preset is the fastest way to fix a uniformly shifted scan across a whole chapter.</p><figure class="shot"><img src="'+o+'" alt="Alignment settings with target language, X, Y and scale inputs, reset buttons and preset controls"><figcaption>Alignment settings: pick the target language, type exact values, or save the current alignment as a page or chapter preset.</figcaption></figure><h2 id="annotations-in-the-compare-reader" tabindex="-1">Annotations in the compare reader <a class="header-anchor" href="#annotations-in-the-compare-reader" aria-label="Permalink to &quot;Annotations in the compare reader&quot;">​</a></h2><p>The annotation toolbar works here too, and compare view is the fastest place to mark a wording difference between the raw and the scanlation.</p><ul><li>New marks follow the same page/panel scope as in the workbench; selecting a panel scopes the next mark to that panel.</li><li>In compare view the layer is shown by default, so marks are visible while you compare. Use the <strong>Annotations</strong> switch to hide them.</li><li>Marks are shared across views: a mark added in the compare reader appears in the panel workbench and in exports.</li><li><code>Esc</code> leaves the current tool; <code>Delete</code> removes the selected mark.</li><li>With a mark selected, <strong>Anchor</strong> in the toolbar turns the canvas into locator mode: click to drop a point, or drag a small box around an area. <strong>Clear anchor</strong> removes it.</li><li><strong>Leader</strong> is on by default and draws the line from the mark to its locator. Text and badge callouts without an anchor fall back to the owning panel, so older annotations still get a sensible line. Turn the switch off to keep the mark alone.</li><li>Anchors are stored in page coordinates, so they stay glued to the artwork while you pan, zoom or switch languages. All three export paths — PNG, HTML and Word (baked annotations) — draw the locator marker and leader exactly as the editor shows them.</li></ul><h3 id="marks-belong-to-a-language" tabindex="-1">Marks belong to a language <a class="header-anchor" href="#marks-belong-to-a-language" aria-label="Permalink to &quot;Marks belong to a language&quot;">​</a></h3><p>Each mark is tagged with the language lane it was drawn in. Drawing an arrow in the Japanese pane does not put it on the Chinese or English version; the same panel can carry a different mark for each edition. A single toggle shares one mark with all languages when the point is about the edition as a whole.</p><p>The switch is deliberate: a note about a translator&#39;s word choice usually makes sense in one lane only, while a box around a sound effect belongs everywhere.</p><h3 id="right-click-menus" tabindex="-1">Right-click menus <a class="header-anchor" href="#right-click-menus" aria-label="Permalink to &quot;Right-click menus&quot;">​</a></h3><p>Right-click a mark for its own menu:</p><ul><li><strong>Delete</strong> the mark.</li><li><strong>Colour</strong> — pick another colour without redrawing.</li><li><strong>Copy to language</strong> — duplicate the mark into another lane, keeping its geometry.</li></ul><p>Right-click empty artwork for the pane menu: <strong>view the image enlarged</strong>, hide this language, mask it, show only this language, show all languages, reset the pane zoom, export this panel as PNG, copy panel coordinates, set the panel number, toggle panel numbers, and insert a link. The same menu is available in read-only mode where it does not write anything.</p><h2 id="a-practical-comparison-loop" tabindex="-1">A practical comparison loop <a class="header-anchor" href="#a-practical-comparison-loop" aria-label="Permalink to &quot;A practical comparison loop&quot;">​</a></h2><ol><li>Open a page in <strong>Compare</strong> (<code>C</code>).</li><li>Enable <code>JA</code> + <code>ZH</code> (and <code>EN</code> if available — or whichever languages the volume has), in the order you want to read.</li><li>Choose <strong>Per-panel offset</strong> if the editions differ per panel; otherwise start with <strong>Whole-page offset</strong>.</li><li>Drag each language&#39;s pane until the panel contents line up.</li><li>Save an alignment preset if the rest of the chapter shares the offset.</li><li>Switch to <strong>Overlay</strong> with Multiply to spot differences in line art or lettering.</li><li>Turn on masks to test yourself, then reveal each pane.</li></ol><h2 id="behaviour-details" tabindex="-1">Behaviour details <a class="header-anchor" href="#behaviour-details" aria-label="Permalink to &quot;Behaviour details&quot;">​</a></h2><ul><li>Alignment offsets are applied at export time too, so the exported crop matches what you see.</li><li>The reader needs panels first. If a page has none, it shows a hint to visit the panel workbench.</li><li>Switching pages keeps the mask preference but clears temporary reveals.</li><li>Each pane carries a note count; selecting a panel here scopes a new note to that panel in the shared notes column.</li><li>Missing languages show placeholders rather than empty panes.</li></ul><figure class="shot"><img src="'+n+'" alt="Compare toolbar with language chips, mask mode, side-by-side and overlay, alignment scope and the drag switch for the current panel"><figcaption>The compare toolbar: language chips, mask mode, side-by-side / overlay, alignment scope and the drag switch for the current panel.</figcaption></figure><h2 id="panel-detail-view" tabindex="-1">Panel detail view <a class="header-anchor" href="#panel-detail-view" aria-label="Permalink to &quot;Panel detail view&quot;">​</a></h2><p>Double-click a panel row to open it full-size. The whole row is the target — the language panes, the head with the panel number, and the blank margins around a crop all open the same panel. Clicks inside editors, drag handles, buttons and links are excluded, and on touch layouts a double-tap on the row does the same thing.</p><ul><li><strong>Page layout</strong> — <strong>Auto</strong>, <strong>Side by side</strong> (artwork left, notes right) or <strong>Stacked</strong> (artwork on top, notes below). Auto follows the window width; when the window is too narrow for two columns the view says so and stacks, instead of squeezing both.</li><li><strong>Draggable splitter</strong> — in the two-column layout the divider between artwork and notes can be dragged, or moved with the arrow keys when focused. The chosen ratio is remembered across panels, pages and reloads.</li><li><strong>Language panes</strong> — <strong>Horizontal</strong> keeps the languages side by side; <strong>Vertical</strong> stacks them full-width, which is what you want in a narrow window or on a tall screen. The choice is remembered, and a narrow window falls back to vertical automatically.</li><li><strong>Alignment by dragging</strong> — drag the artwork itself to nudge that language&#39;s offset. With <strong>Sync move</strong> off, only the lane you touch moves; with it on, dragging one language moves every language together. Zoom follows the same switch, so &quot;make them all 10% bigger&quot; is one drag or one click.</li><li><strong>Exact values</strong> — the Align drawer still exposes each language&#39;s <code>Δx</code> / <code>Δy</code>, 1% arrow nudges, zoom − / + and a per-language reset, plus <strong>Reset all</strong>.</li><li>These detail-view adjustments last for the current session only; they do not write back to the page or the saved alignment.</li><li><strong>Zoom</strong> — the wheel or a pinch over an image zooms the lane under the pointer; the header has zoom buttons and <strong>Fit width</strong>. <strong>Reset</strong> clears the zoom and every Δ at once.</li><li>The notes column uses the same editor as the sidebar and writes directly to this panel; changing panels, paging or going back flushes the draft first.</li><li><strong>Navigation bar</strong> — the detail view&#39;s footer sits outside the scrolling area, so it never covers the art or the notes: previous page and previous panel on the left, next panel and next page on the right. On desktop the buttons show words; on narrow screens they collapse to icons with tooltips. At a page edge, previous panel jumps to the last panel of the previous page and next panel to the first panel of the next page — the detail view stays open, and the URL follows the new page and panel.</li><li><strong>Leaving</strong> — <code>Esc</code>, the <strong>Back</strong> button and the browser back button all return to the same page and panel you came from. The URL is a deep link (<code>…/compare/panel/&lt;id&gt;</code>), so a reload or a shared link reopens the same panel; <code>Alt</code>/<code>Cmd</code>-clicking a row opens it in a new tab.</li></ul><h2 id="enlarged-image-viewer" tabindex="-1">Enlarged image viewer <a class="header-anchor" href="#enlarged-image-viewer" aria-label="Permalink to &quot;Enlarged image viewer&quot;">​</a></h2><p>Right-click a pane and choose <strong>View image enlarged</strong> (the same command is in the detail view&#39;s pane menu) to inspect the artwork without leaving the reader.</p><ul><li>The image is shown at its original resolution, with wheel zoom and drag to pan — useful for checking a glyph, a dotted screentone or a retouch seam.</li><li><strong>Switch language</strong> inside the viewer to compare the same moment across editions without closing it.</li><li><strong>Previous / next</strong> move through panels in reading order, so you can inspect a whole page of small art quickly.</li><li><code>Esc</code> or a click on the backdrop closes it. The page keeps its previous zoom, scroll position and any note draft; nothing is saved or changed by looking.</li><li>It is available in read-only mode too, because it never writes.</li></ul><h2 id="original-view" tabindex="-1">Original view <a class="header-anchor" href="#original-view" aria-label="Permalink to &quot;Original view&quot;">​</a></h2><p>The <strong>Original</strong> view (<code>O</code>) shows the uncropped page for each active language side by side, with wheel zoom from 0.5× to 6×, drag to pan, and the same per-language masks. It is the place to check what sits outside the detected panels.</p><ul><li><strong>Linked / independent</strong> — the toggle in the original-view toolbar decides whether pan and zoom are shared. In <strong>Linked</strong> mode, dragging or zooming one column applies the same relative position and scale to every column; each column resolves those fractions against its own displayed size, so pages of different dimensions stay aligned. <strong>Independent</strong> mode keeps a separate view per column.</li><li>Turning linking on adopts the first visible column&#39;s current view and applies it to the others.</li><li>The setting is remembered per browser in <code>localStorage</code> (<code>manga-memo.original-linked</code>), is on by default, and only matters when two or more languages are displayed.</li></ul><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><ul><li><strong>“This page has no panels yet.”</strong> Go to <strong>Panels</strong> (<code>P</code>) and run <strong>Auto split</strong>, then come back.</li><li><strong>I dragged but the other languages moved.</strong> In Overlay mode, check the <strong>Aligning</strong> chip; only the selected language is dragged.</li><li><strong>Scale drifted.</strong> Per-panel zoom and per-panel offset are stored separately from the whole-page values. Reset the current panel if a test zoom was left behind.</li><li><strong>The pane jumps while scrolling.</strong> The wheel is captured only inside a pane; move the pointer to the page margin to scroll normally.</li><li><strong>Masks appear in a screenshot.</strong> Masks are a UI preference and are not part of exports, but a normal screen capture will show them.</li><li><strong>A chip is greyed out.</strong> That language has no image on this page. Check the library warning or the volume language mapping.</li></ul><h2 id="missing-screenshots" tabindex="-1">Missing screenshots <a class="header-anchor" href="#missing-screenshots" aria-label="Permalink to &quot;Missing screenshots&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figure</th><th>Needed for</th></tr></thead><tbody><tr><td>anchor mode step 1 / step 2</td><td>Reference point and computed offset</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/KomaYomi-docs/guide/panels">Panel Workbench</a> — panels must exist first.</li><li><a href="/KomaYomi-docs/guide/notes">Notes</a> — write down what you notice.</li><li><a href="/KomaYomi-docs/guide/remote">Remote Storage &amp; Backup</a> — behaviour when an image is not cached locally.</li></ul>',57)])])}const k=r(h,[["render",d]]);export{b as __pageData,k as default};
